/*

For #WCCChallenge "Tunnel"


*/


let tunnelShader;
let angle = 0;


async function setup() { // P5JS2: ELECTRIC BOOGALOO!


  createCanvas(600, 600, WEBGL);
  noStroke();


    tunnelShader = await loadShader('https://openprocessing.org/sketch/2984802/files/shader.vert','shader.frag');




}

function draw() {
  background(255,0,0);

  shader(tunnelShader);
  tunnelShader.setUniform('u_time', millis() / 1500.0);
  tunnelShader.setUniform('u_resolution', [width, height]);

  push();
  let t = millis() / 2000;

  translate(100*cos(angle), 100*sin(angle));
  rotateX(t);
  rotateY(t);
  rotateZ(t);
  // Heartbeat pulse
  let pulse = 2.0 + 0.1 * sin(millis() / 200);
  scale(pulse);

  drawHeart3D();
  pop();

  angle +=0.02;

}


function drawHeart3D() {
  let scaler = 8;
  let segments = 60;
  let depth = 20;

  function heartPoint(t) {
    let x = 16 * pow(sin(t), 3);
    let y = -(13 * cos(t) - 5 * cos(2*t) - 2 * cos(3*t) - cos(4*t));
    return { x: x * scaler, y: y * scaler };
  }

  let minX = -16 * scaler;
  let maxX = 16 * scaler;
  let minY = -17 * scaler;
  let maxY = 15 * scaler;

  // FRONT FACE 
  beginShape();
  for (let i = 0; i < segments; i++) {
    var t = map(i, 0, segments, 0, TWO_PI);
    let p = heartPoint(t);
    let u = map(p.x, minX, maxX, 0, 1);
    let v = map(p.y, minY, maxY, 0, 1);
    vertex(p.x, p.y, depth/2, u, v);
  }
  endShape(CLOSE);

  //  BACK FACE 
  beginShape();
  for (let i = segments - 1; i >= 0; i--) {
    var t = map(i, 0, segments, 0, TWO_PI);
    var p = heartPoint(t);
    var u = map(p.x, minX, maxX, 0, 1);
    var v = map(p.y, minY, maxY, 0, 1);
    vertex(p.x, p.y, -depth/2, u, v);
  }
  endShape(CLOSE);

  // EDGE STRIP 
  beginShape(TRIANGLE_STRIP);
  for (let i = 0; i <= segments; i++) {
    var t = map(i % segments, 0, segments, 0, TWO_PI);
    var p = heartPoint(t);
    var u = i / segments;

    vertex(p.x, p.y, depth/2,  u, 0);  // front edge
    vertex(p.x, p.y, -depth/2, u, 1);  // back edge
  }
  endShape();
}

// === Tab: shader.vert ===
#version 300 es
precision highp float;

in vec3 aPosition;
in vec2 aTexCoord;

uniform mat4 uModelViewMatrix;  //fill canvas
uniform mat4 uProjectionMatrix;

out vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
}

// === Tab: shader.frag ===
#version 300 es
precision highp float;

uniform float u_time;
uniform vec2 u_resolution;

in vec2 vTexCoord;

out vec4 fragColor;

void main() {
  vec2 uv = (vTexCoord - 0.5) * vec2(u_resolution.x / u_resolution.y, 1.0);

  uv.y += sin(u_time) * 0.2;  // movement
  uv.x += cos(u_time) * 0.3;

  float angle = atan(uv.y, uv.x);
  float radius = length(uv);

  float speed = 0.5;
  float depth = 10.0;

  float z = u_time * speed + 1.0 / (radius + 0.1);

  float stripes = sin(z * depth + angle * 3.0);

  vec3 color = vec3(
    0.5 + 0.5 * sin(z + 0.0),
    0.5 + 0.5 * sin(z + 2.0),
    0.5 + 0.5 * sin(z + 4.0)
  );

  color *= smoothstep(0.0, 0.5, stripes);

  fragColor = vec4(color, 1.0);
}

